import{d as k,C as l,o as q,c as P,j as n,a as e,E as a,a3 as w}from"./chunks/framework.D4-ViStF.js";const C=JSON.parse('{"title":"庄子·在宥","description":"在宥天下之害到心养无为、天道人道，理解庄子对治天下的根本态度。","frontmatter":{"title":"庄子·在宥","description":"在宥天下之害到心养无为、天道人道，理解庄子对治天下的根本态度。","category":"guide","aliases":["在宥","庄子在宥","zhuangzi chapter 11"],"source":["《庄子·在宥》"]},"headers":[],"relativePath":"daoism/zhuang-zi/chapter-11.md","filePath":"daoism/zhuang-zi/chapter-11.md","lastUpdated":1788516578000}'),j={name:"daoism/zhuang-zi/chapter-11.md"},v=k({...j,setup(T){const d=[{id:"zaiyou",sentences:[["闻在宥天下，不闻治天下也。在之也者，",{text:"恐天下之淫其性也",glossary:"zaiyouzhi"},"；宥之也者，恐天下之迁其德也。天下不淫其性，不迁其德，有治天下者哉？"],["昔尧之治天下也，使天下欣欣焉人乐其性，是不恬也；桀之治天下也，使天下瘁瘁焉人苦其性，是不愉也。夫不恬不愉，非德也。非德也而可长久者，天下无之。"]]}],o=[{id:"yingrenxin",sentences:[["人大喜邪，",{text:"毗于阳",glossary:"piyuyang"},"；大怒邪，毗于阴。阴阳并毗，四时不至，寒暑之和不成，其反伤人之形乎！"],["使人喜怒失位，居处无常，思虑不自得，中道不成章。于是乎天下始乔诘卓鸷，而后有盗跖、曾、史之行。"],["故举天下以赏其善者不足，举天下以罚其恶者不给。故天下之大不足以赏罚。自三代以下者，匈匈焉终以赏罚为事，彼何暇安其",{text:"性命之情",glossary:"xingmingzhiqing"},"哉！"]]}],p=[{id:"piyuyang",term:"毗于阳",pinyin:"pí yú yáng",meaning:"毗：偏倚、损伤。偏倚于阳（阳气过盛）。人大喜邪，毗于阳：人极度欢喜则阳气偏盛。"},{id:"xingmingzhiqing",term:"性命之情",pinyin:"xìng mìng zhī qíng",meaning:"本性与生命的真实情感，本然的生命状态。非被激发的喜怒，非被规范的善恶，而是本然自足的生命。"}],g=[{id:"bazi",sentences:[["而且说明邪，是淫于色也；说聪邪，是淫于声也；说仁邪，是乱于德也；说义邪，是悖于理也；说礼邪，是相于技也；说乐邪，是相于淫也；说圣邪，是相于艺也；说知邪，是相于疵也。"],["天下将安其性命之情，之八者，存可也，亡可也。天下将不安其性命之情，之八者，乃始脔卷𪺷囊而乱天下也。而天下乃始尊之惜之。甚矣，天下之惑也！岂直过也而去之邪！乃齐戒以言之，跪坐以进之，鼓歌以余儛之。吾若是何哉！"],["故君子不得已而临莅天下，莫若无为。无为也，而后安其性命之情。"],["故贵以身于为天下，则可以托天下；爱以身于为天下，则可以寄天下。"],["故君子苟能无解其五藏，无擢其聪明，",{text:"尸居而龙见",glossary:"shiju"},"，渊默而雷声，神动而天随，从容无为而万物炊累焉。吾又何暇治天下哉！"]]}],m=[{id:"shiju",term:"尸居而龙见",pinyin:"shī jū ér lóng xiàn",meaning:"尸居：像尸体一样安静地居处；龙见：像龙一样显现（威仪自现）。静如尸，动如龙。"}],h=[{id:"guangchengzi",sentences:[["崔瞿问于老聃曰：「不治天下，安藏人心？」老聃曰：「女慎，",{text:"无撄人心",glossary:"wuying"},"。"],["人心排下而进上，上下囚杀，淖约柔乎刚强，廉刿雕琢，其热焦火，其寒凝冰，其疾俯仰之间而再抚四海之外。其居也，渊而静；其动也，县而天。",{text:"偾骄而不可系",glossary:"fenjiao"},"者，其唯人心乎！"],["昔者黄帝始以仁义撄人之心，尧、舜于是乎股无胈，胫无毛，以养天下之形。愁其五藏以为仁义，矜其血气以规法度。然犹有不胜也。"],["尧于是放讙兜于崇山，投三苗于三峗，流共工于幽都，此不胜天下也。夫施及三王而天下大骇矣。下有桀、跖，上有曾、史，而儒墨毕起。于是乎喜怒相疑，愚知相欺，善否相非，诞信相讥，而天下衰矣；大德不同，而性命烂漫矣；天下好知，而百姓求竭矣。于是乎斤锯制焉，绳墨杀焉，椎凿决焉。天下脊脊大乱，",{text:"罪在撄人心",glossary:"zuiying"},"。"],["故贤者伏处大山嵁岩之下，而万乘之君忧栗乎庙堂之上。今世殊死者相枕也，桁杨者相推也，形戮者相望也，而儒墨乃始离跂攘臂乎桎梏之间。意，甚矣哉！其无愧而不知耻也甚矣！"],["吾未知圣知之不为桁杨椄槢也，仁义之不为桎梏凿枘也，焉知曾、史之不为桀、跖",{text:"嚆矢",glossary:"haoshi"},"也！故曰：",{text:"绝圣弃知",glossary:"juesheng"},"，而天下大治。"],["黄帝立为天子十九年，令行天下，闻广成子在于空同之上，故往见之，曰：「我闻吾子达于至道，敢问至道之精。吾欲取天地之精，以佐五谷，以养民人。吾又欲官阴阳以遂群生，为之奈何？」"],["广成子曰：「而所欲问者，物之质也；而所欲官者，物之残也。自而治天下，云气不待族而雨，草木不待黄而落，日月之光益以荒矣，而佞人之心翦翦者，又奚足以语至道！」"],["黄帝退，捐天下，筑特室，席白茅，闲居三月，复往邀之。广成子南首而卧，黄帝顺下风膝行而进，再拜稽首而问曰：「闻吾子达于至道，敢问：治身奈何而可以长久？」"],["广成子蹶然而起，曰：「善哉问乎！来，吾语女至道：至道之精，窈窈冥冥；至道之极，昏昏默默。无视无听，抱神以静，形将自正。必静必清，无劳女形，无摇女精，乃可以长生。目无所见，耳无所闻，心无所知，女神将守形，形乃长生。慎女内，闭女外，",{text:"多知为败",glossary:"duozhi"},"。"],["我为女遂于大明之上矣，至彼至阳之原也；为女入于窈冥之门矣，至彼至阴之原也。天地有官，阴阳有藏。慎守女身，物将自壮。我",{text:"守其一以处其和",glossary:"shouqiyi"},"。故我修身千二百岁矣，吾形未常衰。」"],["黄帝再拜稽首曰：「广成子之谓天矣！」广成子曰：「来！余语女：彼其物无穷，而人皆以为有终；彼其物无测，而人皆以为有极。得吾道者，上为皇而下为王；失吾道者，上见光而下为土。今夫百昌皆生于土而反于土。故余将去女，入无穷之门，以游无极之野。吾与日月参光，吾与天地为常。当我缗乎，远我昏乎！人其尽死，而我独存乎！」"]]}],y=[{id:"wuying",term:"无撄人心",pinyin:"wú yīng rén xīn",meaning:"撄：触动、扰乱。不要扰乱人心。老聃的核心警告。"},{id:"fenjiao",term:"偾骄而不可系",pinyin:"fèn jiāo ér bù kě xì",meaning:"偾：奔腾；骄：不驯。奔腾不驯而无法束缚。描述人心的本质——最强大、最不可控。"},{id:"zuiying",term:"罪在撄人心",pinyin:"zuì zài yīng rén xīn",meaning:"罪过在于扰乱了人心。无论动机好坏，撄人心都会导致人心失衡，天下大乱。"},{id:"haoshi",term:"嚆矢",pinyin:"hāo shǐ",meaning:"响箭，发出声音的箭，比喻先导、开端。「曾史是桀跖嚆矢」——极善，是极恶的先导。"},{id:"juesheng",term:"绝圣弃知",pinyin:"jué shèng qì zhī",meaning:"断绝圣人之道，抛弃机巧之知。《胠箧》与《在宥》共同的核心命题。"},{id:"duozhi",term:"多知为败",pinyin:"duō zhī wéi bài",meaning:"过多的知识是失败的根源。广成子对黄帝的核心教导。"},{id:"shouqiyi",term:"守其一以处其和",pinyin:"shǒu qí yī yǐ chǔ qí hé",meaning:"守住那个「一」（道的本体），处于阴阳的和谐之中。广成子修身千二百岁的根本方法。"}],u=[{id:"xinyang",sentences:[["云将东游，过扶摇之枝而适遭鸿蒙。鸿蒙方将",{text:"拊脾雀跃",glossary:"fupique"},"而游。云将见之，倘然止，贽然立，曰：「叟何人邪？叟何为此？」鸿蒙拊脾雀跃不辍，对云将曰：「游！」"],["云将曰：「朕愿有问也。」鸿蒙仰而视云将曰：「吁！」云将曰：「天气不和，地气郁结，六气不调，四时不节。今我愿合六气之精以育群生，为之奈何？」鸿蒙拊脾雀跃掉头曰：「吾弗知！吾弗知！」"],["云将不得问。又三年，东游，过有宋之野，而适遭鸿蒙。云将大喜，行趋而进曰：「天忘朕邪？天忘朕邪？」再拜稽首，愿闻于鸿蒙。"],["鸿蒙曰：「浮游不知所求，猖狂不知所往，游者鞅掌，以观无妄。朕又何知！」云将曰：「朕也自以为猖狂，而民随予所往；朕也不得已于民，今则民之放也！愿闻一言。」"],["鸿蒙曰：「乱天之经，逆物之情，玄天弗成，解兽之群而鸟皆夜鸣，灾及草木，祸及止虫。意！治人之过也。」"],["云将曰：「然则吾奈何？」鸿蒙曰：「意！毒哉！僊僊乎归矣！」云将曰：「吾遇天难，愿闻一言。」"],["鸿蒙曰：「意！",{text:"心养",glossary:"xinyang"},"！汝徒处无为，而物自化。",{text:"堕尔形体，吐尔聪明",glossary:"duoer"},"，伦与物忘，大同乎涬溟。解心释神，莫然无魂。"],["万物云云，各复其根，各复其根而不知。浑浑沌沌，终身不离。",{text:"若彼知之，乃是离之",glossary:"ruobi"},"。无问其名，无窥其情，物固自生。」"],["云将曰：「天降朕以德，示朕以默。躬身求之，乃今得也。」再拜稽首，起辞而行。"]]}],x=[{id:"fupique",term:"拊脾雀跃",pinyin:"fǔ pí què yuè",meaning:"拊：拍打；脾：大腿。拍打大腿、像雀一样跳跃（无拘无束地嬉游）。"},{id:"xinyang",term:"心养",pinyin:"xīn yǎng",meaning:"养心，涵养内心。鸿蒙给云将的全部答案。具体内容：堕形体·吐聪明·伦与物忘·大同乎涬溟·解心释神·莫然无魂。"},{id:"duoer",term:"堕尔形体，吐尔聪明",pinyin:"duò ěr xíng tǐ，tǔ ěr cōng míng",meaning:"堕：放下、忘却；吐：吐出、放弃。放下对身体的执着，放弃对聪明的依赖。"},{id:"ruobi",term:"若彼知之，乃是离之",pinyin:"ruò bǐ zhī zhī，nǎi shì lí zhī",meaning:"如果他知道（意识到）这个状态，就已经离开这个状态了。《在宥》最深的认识论命题：道，不可以被「知道」。"}],b=[{id:"youtuzhe",sentences:[["世俗之人，皆喜人之同乎己而恶人之异于己也。同于己而欲之，异于己而不欲者，以出乎众为心也。夫以出乎众为心者，曷常出乎众哉？因众以宁所闻，不如众技众矣。"],["而欲为人之国者，此揽乎三王之利而不见其患者也。此以人之国侥幸也。几何侥幸而不丧人之国乎？其存人之国也，无万分之一；而丧人之国也，一不成而万有余丧矣！悲夫，有土者之不知也！"],["夫有土者，有大物也。有大物者，不可以物。",{text:"物而不物，故能物物",glossary:"wuerbwu"},"。明乎物物者之非物也，岂独治天下百姓而已哉！出入六合，游乎九州，独往独来，是谓独有。独有之人，是之谓至贵。"],["大人之教，若形之于影，声之于响，有问而应之，尽其所怀，为天下配。处乎无响。行乎无方。挈汝适复之，挠挠以游无端，出入无旁，与日无始。颂论形躯，合乎大同。大同而无己。无己，恶乎得有有。睹有者，昔之君子；睹无者，天地之友。"],["贱而不可不任者，物也；卑而不可不因者，民也；匿而不可不为者，事也；粗而不可不陈者，法也；远而不可不居者，义也；亲而不可不广者，仁也；节而不可不积者，礼也；中而不可不高者，德也；一而不可不易者，道也；神而不可不为者，天也。"],["故圣人观于天而不助，成于德而不累，出于道而不谋，会于仁而不恃，薄于义而不积，应于礼而不讳，接于事而不辞，齐于法而不乱，恃于民而不轻，因于物而不去。物者莫足为也，而不可不为。"],["不明于天者，不纯于德；不通于道者，无自而可；不明于道者，悲夫！何谓道？有天道，有人道。无为而尊者，天道也；有为而累者，人道也。主者，天道也；臣者，人道也。天道之与人道也，相去远矣，不可不察也。"]]}],c=[{id:"wuerbwu",term:"物而不物，故能物物",pinyin:"wù ér bù wù，gù néng wù wù",meaning:"接触事物但不被事物役使，所以才能主宰万物使其各得其所。不是强制管理，而是让万物自然各归其位。"}];return(z,i)=>{const f=l("DaoReadingPrelude"),t=l("DaoTextReading"),r=l("DaoKeywordCards"),s=l("DaoLineGuide");return q(),P("div",null,[i[0]||(i[0]=n("h1",{id:"庄子·在宥",tabindex:"-1"},[e("庄子·在宥 "),n("a",{class:"header-anchor",href:"#庄子·在宥","aria-label":'Permalink to "庄子·在宥"'},"​")],-1)),i[1]||(i[1]=n("h2",{id:"篇名释义",tabindex:"-1"},[e("篇名释义 "),n("a",{class:"header-anchor",href:"#篇名释义","aria-label":'Permalink to "篇名释义"'},"​")],-1)),i[2]||(i[2]=n("blockquote",null,[n("p",null,[n("strong",null,"「在宥天下，不闻治天下也。」")]),n("p",null,"《在宥》是《庄子》外篇第四篇，紧承《胠箧》之后。《胠箧》说：圣人生而大盗起——掊击圣人，天下始治。《在宥》说：闻在宥天下，不闻治天下——天下之乱，根在撄人心；天下之治，在于无为。"),n("p",null,"两篇，是同一个批判的两面：《胠箧》从外部说——圣人之知为大盗所用；《在宥》从内部说——治天下的行为本身，伤害了人心与本性。"),n("p",null,[n("strong",null,"「在宥」——在：自在，让其自在；宥：宽容，不加干涉。「在宥天下」：让天下自在，宽容天下，不加干涉——这，才是庄子心目中对待天下的正确方式。")])],-1)),a(f,{title:"从在宥天下到心养无为、天道人道",summary:"《在宥》开篇立「在宥天下，不闻治天下」的命题，经撄人心之害、八者存亡、老聃论撄人心与黄帝问广成子，再到云将问鸿蒙的「心养」、有土者大物的「物而不物」，最后以「天道人道」收束——治天下的最高境界，不是「治」，而是「在宥」；不是撄人心，而是养心。",points:[{label:"先看",text:"顺着在宥→撄心→八者→老聃广成子→鸿蒙→有土者这条线走一遍。"},{label:"再问",text:"为什么「撄人心」是罪？好的动机为什么会带来坏的结果？"},{label:"最后",text:"「心养」在今天意味着什么？你分得清天道与人道吗？"}],hint:"这是外篇批判主题的收束篇。读完后可以回看《骈拇》《马蹄》《胠箧》，四篇构成外篇对「有为」的完整批判链。"}),i[3]||(i[3]=n("h2",{id:"一、在宥天下·不闻治天下",tabindex:"-1"},[e("一、在宥天下·不闻治天下 "),n("a",{class:"header-anchor",href:"#一、在宥天下·不闻治天下","aria-label":'Permalink to "一、在宥天下·不闻治天下"'},"​")],-1)),i[4]||(i[4]=n("h3",{id:"原文",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:d,glossary:z.zaiyouGlossary,"default-mode":"classic","aria-label":"在宥·在宥天下 原文"},null,8,["glossary"]),i[5]||(i[5]=n("h3",{id:"生僻字词",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"在宥天下",pinyin:["zài","yòu"],meaning:"在：自在，使其自在；宥：宽容，不加干涉。让天下自在宽容，不加干涉。"},{term:"治天下",pinyin:["zhì"],meaning:"治：治理、管理。主动治理天下。"},{term:"淫其性",pinyin:["yín","qí","xìng"],meaning:"淫：过度、放纵、扰乱。扰乱、放纵本性（使本性失去节度）。"},{term:"迁其德",pinyin:["qiān","qí","dé"],meaning:"迁：迁移、改变。改变、迁移本真之德。"},{term:"欣欣焉",pinyin:["xīn","xīn"],meaning:"欣欣：喜悦、兴奋的样子。"},{term:"人乐其性",pinyin:["rén","lè","qí","xìng"],meaning:"人们以自己的本性为乐（刻意追求快乐）。"},{term:"是不恬也",pinyin:["tián"],meaning:"恬：安静、淡泊。这不是真正的安静淡泊。"},{term:"瘁瘁焉",pinyin:["cuì","cuì"],meaning:"瘁：憔悴、痛苦的样子。"},{term:"人苦其性",pinyin:["rén","kǔ","qí","xìng"],meaning:"人们以自己的本性为苦（被迫受苦）。"},{term:"是不愉也",pinyin:["yú"],meaning:"愉：愉悦、舒适。这不是真正的愉悦舒适。"},{term:"非德也",pinyin:["fēi","dé","yě"],meaning:"不是真正的德（本真之德）。"}]}),i[6]||(i[6]=n("h3",{id:"核心句引读",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(s,{title:"闻在宥天下，不闻治天下也",subtitle:"「在宥」的动机是「恐」——是担心，是保护——以「不干涉」的方式实现。",lines:[{text:"闻在宥天下，不闻治天下也。",tone:"开篇",guide:"《在宥》开篇，一句话，建立全篇的核心命题——闻在宥天下（听说过让天下自在宽容的），不闻治天下也（没听说过治理天下的）。「闻……不闻」——这个句式，极为精准：不是说「治天下是错的」——而是说：「在宥天下」这件事，是有人做过的；「治天下」这件事，从来没有真正做到过——因为「治」，本身就是问题所在。"},{text:"在之也者，恐天下之淫其性也；宥之也者，恐天下之迁其德也。",tone:"动机",guide:"庄子解释「在宥」的动机——在之（让其自在），恐天下之淫其性（是担心天下扰乱了自己的本性）；宥之（宽容不干涉），恐天下之迁其德（是担心天下改变了自己的本真之德）。「在宥」的目的，是保护——不是积极地给予，而是消极地保护——让本性不被扰乱，让本德不被改变——这，才是对天下真正的善待。"},{text:"昔尧之治天下也，使天下欣欣焉人乐其性，是不恬也；桀之治天下也，使天下瘁瘁焉人苦其性，是不愉也。夫不恬不愉，非德也。",tone:"尧桀",guide:"庄子用两个极端的例子——尧（儒家最推崇的圣王）与桀（历史上最著名的暴君）——来证明「治天下」的根本问题：尧之治——欣欣焉，人乐其性——是不恬也（天下欣欣向荣，人们以自己的本性为乐——但这不是真正的「恬」，因为「乐其性」是刻意的，是被激发出来的）；桀之治——瘁瘁焉，人苦其性——是不愉也（天下憔悴痛苦，人们以自己的本性为苦）。夫不恬不愉，非德也——无论是尧的「欣欣」，还是桀的「瘁瘁」——都不是真正的德——因为两者，都是「治天下」造成的——都是外力干涉本性的结果。这个命题，极为深刻：庄子把尧与桀并列——不是说尧与桀一样坏——而是说：从「治天下」这个行为的本质来看，尧与桀，是同一类——都是在干涉天下的本性，只是一个让人「乐其性」，一个让人「苦其性」——但两者，都不是本性的自然流淌。"}]}),i[7]||(i[7]=n("h2",{id:"二、撄人心之害·喜怒失位·赏罚不给",tabindex:"-1"},[e("二、撄人心之害·喜怒失位·赏罚不给 "),n("a",{class:"header-anchor",href:"#二、撄人心之害·喜怒失位·赏罚不给","aria-label":'Permalink to "二、撄人心之害·喜怒失位·赏罚不给"'},"​")],-1)),i[8]||(i[8]=n("h3",{id:"原文-1",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-1","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:o,glossary:p,"default-mode":"classic","aria-label":"在宥·撄人心之害 原文"}),i[9]||(i[9]=n("h3",{id:"生僻字词-1",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-1","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"毗于阳",pinyin:["pí","yú","yáng"],meaning:"毗：偏倚、损伤。偏倚于阳（阳气过盛）。"},{term:"毗于阴",pinyin:["pí","yú","yīn"],meaning:"偏倚于阴（阴气过盛）。"},{term:"阴阳并毗",pinyin:["yīn","yáng","bìng","pí"],meaning:"阴阳都受到损伤、失去平衡。"},{term:"四时不至",pinyin:["sì","shí","bù","zhì"],meaning:"四季不能正常运行。"},{term:"喜怒失位",pinyin:["xǐ","nù","shī","wèi"],meaning:"喜怒失去了应有的位置（不在本然状态）。"},{term:"居处无常",pinyin:["jū","chù","wú","cháng"],meaning:"居住与处事没有常态。"},{term:"思虑不自得",pinyin:["sī","lǜ","bù","zì","dé"],meaning:"思考与忧虑无法自然得到（内心不安）。"},{term:"中道不成章",pinyin:["zhōng","dào","bù","chéng","zhāng"],meaning:"在行进中无法形成有序的章法。"},{term:"乔诘卓鸷",pinyin:["qiáo","jié","zhuó","zhì"],meaning:"乔：傲慢；诘：诘问、刁难；卓：特立独行；鸷：凶猛。形容天下人变得傲慢、刁钻、偏激、凶猛。"},{term:"匈匈焉",pinyin:["xiōng","xiōng"],meaning:"匈匈：喧嚣、纷乱的样子。"}]}),i[10]||(i[10]=n("h3",{id:"核心句引读-1",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-1","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(s,{title:"撄人心之后，赏罚永远追不上",subtitle:"赏罚是在处理结果，而不是在处理根源。",lines:[{text:"人大喜邪，毗于阳；大怒邪，毗于阴。阴阳并毗，四时不至，寒暑之和不成，其反伤人之形乎！",tone:"阴阳",guide:"第二段，庄子从身体的维度，展开「撄人心」的危害——人大喜，毗于阳（人极度喜悦，阳气偏盛）；大怒，毗于阴（人极度愤怒，阴气偏盛）——阴阳并毗（阴阳都失去平衡）——四时不至，寒暑之和不成——其反伤人之形乎！这一段，是庄子从身体·气·阴阳的维度，来说明情绪失衡的危害——喜怒，本是人的自然情感——但「大喜·大怒」——极度的喜怒——是被外力激发出来的，超出了本然的节度——这种超出节度的喜怒，会扰乱阴阳，进而伤害形体。这与第一段「尧使天下欣欣焉人乐其性」完全对应：尧让天下「大喜」——毗于阳；桀让天下「大怒」——毗于阴——两者，都在伤害天下人的形体。"},{text:"使人喜怒失位，居处无常，思虑不自得，中道不成章。于是乎天下始乔诘卓鸷，而后有盗跖、曾、史之行。",tone:"失序",guide:"喜怒失位（喜怒失去了本然的位置）、居处无常、思虑不自得、中道不成章——四句，描绘了「撄人心」之后，人的内在状态的全面失序——于是乎天下始乔诘卓鸷（天下人开始变得傲慢、刁钻、偏激、凶猛）——而后有盗跖、曾、史之行（然后，才有了盗跖那样的恶行，和曾参、史鱼那样的善行）。这一句，极为精准——盗跖与曾、史，被并列在一起——不是说曾参与盗跖一样坏——而是说：两者，都是「撄人心」之后的产物——本然状态下，没有盗跖，也没有曾、史——因为本然状态下，没有极端的恶，也没有极端的善——极端的恶与极端的善，都是本性失衡之后的两个方向。"},{text:"故举天下以赏其善者不足，举天下以罚其恶者不给。故天下之大不足以赏罚。",tone:"赏罚",guide:"举天下以赏其善者不足——用整个天下来奖赏善人，还不够；举天下以罚其恶者不给——用整个天下来惩罚恶人，还不够用——故天下之大不足以赏罚——天下之大，不足以用来赏罚。这三句，是对「赏罚」这个治理工具的根本否定：赏罚，是「治天下」最基本的工具——但庄子说：天下之大，不足以赏罚——不是说天下太小，而是说：当本性已经失衡，善恶已经极化——赏罚，永远追不上——因为赏罚，是在处理结果，而不是在处理根源。"}]}),i[11]||(i[11]=n("h2",{id:"三、八者存亡·无为临天下",tabindex:"-1"},[e("三、八者存亡·无为临天下 "),n("a",{class:"header-anchor",href:"#三、八者存亡·无为临天下","aria-label":'Permalink to "三、八者存亡·无为临天下"'},"​")],-1)),i[12]||(i[12]=n("h3",{id:"原文-2",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-2","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:g,glossary:m,"default-mode":"classic","aria-label":"在宥·八者存亡 原文"}),i[13]||(i[13]=n("h3",{id:"生僻字词-2",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-2","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"说明邪",pinyin:["yuè","míng","xié"],meaning:"说：喜悦、推崇；明：视觉、明察。推崇明察（视觉的敏锐）。"},{term:"淫于色",pinyin:["yín","yú","sè"],meaning:"过度沉溺于色彩（视觉刺激）。"},{term:"说聪邪",pinyin:["sōng"],meaning:"聪：听觉、听力。推崇聪（听觉的敏锐）。"},{term:"淫于声",pinyin:["yín","yú","shēng"],meaning:"过度沉溺于声音（听觉刺激）。"},{term:"脔卷𪺷囊",pinyin:["luán","juǎn","chǒu","náng"],meaning:"脔：切割；卷：卷缠；𪺷：束缚；囊：装袋。切割、卷缠、束缚、装袋（比喻八者被用来捆绑束缚天下）。"},{term:"尊之惜之",pinyin:["zūn","zhī","xī","zhī"],meaning:"尊崇它、珍惜它。"},{term:"齐戒以言之",pinyin:["zhāi","jiè"],meaning:"齐戒：斋戒，庄重准备。斋戒之后才郑重地谈论它。"},{term:"跪坐以进之",pinyin:["guì","zuò","yǐ","jìn","zhī"],meaning:"跪坐着恭敬地推进它。"},{term:"莫若无为",pinyin:["mò","ruò","wú","wéi"],meaning:"没有比无为更好的了。"},{term:"无解其五藏",pinyin:["wú","jiě","wǔ","zàng"],meaning:"五藏：五脏。不扰动五脏（保持内在的安静）。"},{term:"无擢其聪明",pinyin:["zhuó"],meaning:"擢：拔出、过度使用。不过度使用聪明（不炫耀才智）。"},{term:"尸居而龙见",pinyin:["shī","jū","ér","lóng","xiàn"],meaning:"尸居：像尸体一样安静地居处；龙见：像龙一样显现（威仪自现）。静如尸，动如龙。"},{term:"渊默而雷声",pinyin:["yuān","mò","léi","shēng"],meaning:"渊默：深渊般的沉默；雷声：雷鸣般的声音。默如深渊，发声如雷。"},{term:"神动而天随",pinyin:["shén","dòng","ér","tiān","suí"],meaning:"精神一动，天地随之响应。"}]}),i[14]||(i[14]=n("h3",{id:"核心句引读-2",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-2","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(s,{title:"之八者，存可也，亡可也",subtitle:"如果天下人能安顿本性——这八种东西，有也可以，没有也可以。",lines:[{text:"天下将安其性命之情，之八者，存可也，亡可也。天下将不安其性命之情，之八者，乃始脔卷𪺷囊而乱天下也。",tone:"八者",guide:"这一段，是八者问题的核心：天下将安其性命之情——如果天下人能够安顿自己的本性与生命——之八者，存可也，亡可也——这八种东西，有也可以，没有也可以——它们，无关紧要。天下将不安其性命之情——如果天下人无法安顿自己的本性与生命——之八者，乃始脔卷𪺷囊而乱天下也——这八种东西，就开始切割、卷缠、束缚、装袋，扰乱天下。这是《在宥》最深的一个命题：明·聪·仁·义·礼·乐·圣·知——这八者，本身不是问题——问题在于：天下人能不能安其性命之情。如果能安其性命之情——八者无害；如果不能安其性命之情——八者为害。根源，不在于八者本身，而在于本性是否安顿。"},{text:"故君子不得已而临莅天下，莫若无为。无为也，而后安其性命之情。",tone:"无为",guide:"从感叹，庄子转入正面的建议——故君子不得已而临莅天下，莫若无为（君子，是不得已才去统治天下的——「不得已」三个字极为重要：君子，不是主动去治天下的——主动去治天下的，是那些「说仁说义说圣说知」的人——君子，只有在不得已的情况下，才去临莅天下）。莫若无为——没有比无为更好的了——无为也，而后安其性命之情——无为，然后才能安顿本性与生命的真情实感。「无为」，不是什么都不做——而是：不强为，不干涉，不撄人心——让天下的本性，自然地安顿。"},{text:"故贵以身于为天下，则可以托天下；爱以身于为天下，则可以寄天下。",tone:"贵身",guide:"这两句，化用《老子》十三章——贵以身于为天下（以自身为贵，胜过为天下）——则可以托天下（才可以将天下托付给他）；爱以身于为天下（以爱护自身胜过为天下）——则可以寄天下。这两句，极为深刻——能够被托付天下的人，不是那种「以天下为己任」的人——而是那种「以自身为贵、爱护自身」的人——为什么？因为一个真正珍视自身本性的人，才懂得珍视天下人的本性——一个能安其性命之情的人，才懂得让天下人安其性命之情——这，才是真正可以托付天下的人。反之：那种「舍身为天下」的人——看起来高尚，实则危险——因为他不珍视自身本性，也就不会珍视天下人的本性——他会用「为天下」的名义，撄天下人的心。"},{text:"尸居而龙见，渊默而雷声，神动而天随，从容无为而万物炊累焉。吾又何暇治天下哉！",tone:"境界",guide:"第三段，以这一段华美的描述作结——无解其五藏（不扰动五脏，保持内在安静），无擢其聪明（不过度使用聪明）——尸居而龙见（静处时像尸体一样安静，显现时像龙一样威仪自现），渊默而雷声（沉默时像深渊一样深不可测，发声时像雷鸣一样震动天地），神动而天随（精神一动，天地随之响应），从容无为而万物炊累焉（从容无为，万物自然聚集归附）。这四句，是《在宥》对「无为」境界最生动的描绘：不是软弱，不是消极——而是一种极大的内在力量——静如深渊，动如雷龙——不刻意，而万物自然归附。吾又何暇治天下哉！——我哪里还有时间治理天下呢！"}]}),i[15]||(i[15]=n("h2",{id:"四、老聃论撄人心·黄帝问广成子至道",tabindex:"-1"},[e("四、老聃论撄人心·黄帝问广成子至道 "),n("a",{class:"header-anchor",href:"#四、老聃论撄人心·黄帝问广成子至道","aria-label":'Permalink to "四、老聃论撄人心·黄帝问广成子至道"'},"​")],-1)),i[16]||(i[16]=n("h3",{id:"原文-3",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-3","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:h,glossary:y,"default-mode":"classic","aria-label":"在宥·老聃论撄人心 原文"}),i[17]||(i[17]=n("h3",{id:"生僻字词-3",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-3","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"崔瞿",pinyin:["cuī","jù"],meaning:"人名，庄子虚构的人物，向老聃问道。"},{term:"安藏人心",pinyin:["ān","cáng","rén","xīn"],meaning:"怎么安顿人心？藏：安置、安顿。"},{term:"女慎",pinyin:["rǔ","shèn"],meaning:"女：通「汝」，你。你要谨慎。"},{term:"无撄人心",pinyin:["wú","yīng","rén","xīn"],meaning:"撄：触动、扰乱。不要扰乱人心。老聃的核心警告。"},{term:"排下而进上",pinyin:["pái","xià","ér","jìn","shàng"],meaning:"向下排斥（谦卑）而向上进取（傲慢）。形容人心的矛盾性。"},{term:"上下囚杀",pinyin:["shàng","xià","qiú","shā"],meaning:"向上向下都能囚禁杀戮（人心的危险性）。"},{term:"廉刿雕琢",pinyin:["lián","guì"],meaning:"廉刿：锋利割伤；雕琢：精细雕刻。锋利时能割伤雕琢（人心的锋利性）。"},{term:"其热焦火",pinyin:["qí","rè","jiāo","huǒ"],meaning:"热起来比火还焦烈。"},{term:"其寒凝冰",pinyin:["qí","hán","níng","bīng"],meaning:"冷起来比冰还凝固。"},{term:"股无胈",pinyin:["bì"],meaning:"胈：大腿上的细毛。大腿上没有细毛（因劳累而磨光）。"},{term:"胫无毛",pinyin:["jìng"],meaning:"胫：小腿。小腿上没有毛（因劳累而磨光）。"},{term:"桁杨",pinyin:["háng","yáng"],meaning:"桁杨：套在颈部或脚部的刑具（类似枷锁）。"},{term:"桎梏",pinyin:["zhì","gù"],meaning:"桎：脚镣；梏：手铐。刑具。"},{term:"嚆矢",pinyin:["hāo","shǐ"],meaning:"响箭，发出声音的箭，比喻先导、开端。"},{term:"广成子",pinyin:["guǎng","chéng","zǐ"],meaning:"传说中的仙人，黄帝的老师，居于空同山。"},{term:"多知为败",pinyin:["duō","zhī","wéi","bài"],meaning:"过多的知识是失败的根源。"}]}),i[18]||(i[18]=n("h3",{id:"核心句引读-3",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-3","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(s,{title:"女慎，无撄人心——罪在撄人心",subtitle:"人心不是可以被「治」的——人心，只能被「不撄」。",lines:[{text:"女慎，无撄人心。人心排下而进上，上下囚杀，淖约柔乎刚强，廉刿雕琢，其热焦火，其寒凝冰，其疾俯仰之间而再抚四海之外。其居也，渊而静；其动也，县而天。偾骄而不可系者，其唯人心乎！",tone:"人心",guide:"崔瞿问老聃：「不治天下，安藏人心？」——不治理天下，怎么安顿人心？这个问题，代表了世俗最常见的逻辑：人心需要被安顿，所以需要治天下。老聃的回答，从根本上颠覆了这个逻辑——「女慎，无撄人心。」——你要谨慎——不要扰乱人心。不是「如何安顿人心」——而是「不要扰乱人心」。然后，老聃用七句话，描绘人心的本质——排下而进上（向下排斥，向上进取——人心，既谦卑又傲慢），上下囚杀（向上向下都能囚禁杀戮——人心，有极大的破坏力），淖约柔乎刚强（柔软时无坚不摧），廉刿雕琢（锋利时无物不伤），其热焦火（热起来比火还焦烈），其寒凝冰（冷起来比冰还凝固），其疾俯仰之间而再抚四海之外（快起来，俯仰之间就能两度抚及四海之外）——其居也，渊而静；其动也，县而天——偾骄而不可系者，其唯人心乎！——奔腾不驯而无法束缚的，只有人心！这样的人心，你敢去「撄」它吗？老聃的意思极为清晰：人心，不是可以被「治」的——人心，只能被「不撄」——任何试图「安顿人心」的行为，都是在撄人心——都会激发人心最危险的那一面。"},{text:"天下脊脊大乱，罪在撄人心。",tone:"定罪",guide:"从黄帝到三王——历史的演变——施及三王而天下大骇（延续到三王，天下大为震惊骚乱），下有桀、跖，上有曾、史，而儒墨毕起（下层有极恶，上层有极善，儒家与墨家都兴起了）——这一句，与第2段「而后有盗跖、曾、史之行」完全呼应——极恶与极善，同时出现——这不是偶然，而是「撄人心」的必然结果：本性失衡，向两个极端分化。于是乎喜怒相疑，愚知相欺，善否相非，诞信相讥——而天下衰矣——于是乎斤锯制焉，绳墨杀焉，椎凿决焉——刑具，大量出现——天下脊脊大乱，罪在撄人心——天下纷乱不安地大乱——罪过，在于扰乱了人心。这一句，是老聃这段话的核心结论——与《胠箧》「圣人生而大盗起」完全对应：《胠箧》说：罪在圣人之知；《在宥》说：罪在撄人心——两者，是同一个命题的两种表述。"},{text:"吾未知圣知之不为桁杨椄槢也，仁义之不为桎梏凿枘也，焉知曾、史之不为桀、跖嚆矢也！故曰：绝圣弃知，而天下大治。",tone:"刑具",guide:"老聃最后三句，是《在宥》全篇最深刻的命题——吾未知圣知之不为桁杨椄槢也（我不知道圣人之知，不是桁杨的榫头），仁义之不为桎梏凿枘也（我不知道仁义，不是桎梏的凿枘）——「椄槢」·「凿枘」——都是刑具的榫头部分——圣知，是桁杨的榫头——没有它，桁杨无法成形；仁义，是桎梏的凿枘——没有它，桎梏无法锁紧——圣知与仁义，是刑具的核心部件。这比《胠箧》「为之仁义则并与仁义而窃之」更深一层：《胠箧》说仁义被大盗窃取；《在宥》说仁义本身就是刑具的一部分。焉知曾、史之不为桀、跖嚆矢也！——怎么知道曾参、史鱼，不是桀与盗跖的响箭（先导）呢！——「嚆矢」——响箭，比喻先导——曾参、史鱼的极善——是桀与盗跖极恶的先导——这是《在宥》最惊世骇俗的一句：极善，导致极恶——有多高的曾史，就有多深的桀跖。故曰：绝圣弃知，而天下大治。"},{text:"广成子曰：至道之精，窈窈冥冥；至道之极，昏昏默默。无视无听，抱神以静，形将自正。……慎女内，闭女外，多知为败。",tone:"至道",guide:"老聃论撄人心之后，庄子转入第一则寓言——黄帝问广成子。黄帝第一次的问题，是一个治者的问题：如何利用至道来治理天下、养育万民——至道，在黄帝眼中，是一种治理工具。广成子的回答，极为严厉：而所欲问者，物之质也（你想问的，只是事物的表面）；而所欲官者，物之残也（你想管理的，只是事物的末节）——自从你治理天下以来——云气不待族而雨，草木不待黄而落，日月之光益以荒矣——「治天下」，不只伤害人——还伤害了天地自然的运行。黄帝被拒绝之后——退，捐天下，筑特室，席白茅，闲居三月——这是黄帝的转变：从「治天下」，到「捐天下」。三个月后，黄帝再次拜访，问的问题完全变了：「治身奈何而可以长久？」——从「治天下」到「治身」，从外转内，从治人转为治己。广成子蹶然而起，说「善哉问乎！」——两次问，两种回应——问题的方向，决定了能否得到答案。广成子的回答：至道之精，窈窈冥冥；至道之极，昏昏默默——至道，不是可以言说的——只能体验，不能描述。无视无听，抱神以静，形将自正——不是主动去端正形体——而是当你不视不听，抱神以静——形体，自然就端正了。慎女内，闭女外，多知为败——「多知为败」——这一句，是广成子回答的核心——也是对黄帝第一次问题的直接否定：你第一次来，问的是「取天地之精·官阴阳」——那是「多知」——多知，是败。"},{text:"我守其一以处其和。故我修身千二百岁矣，吾形未常衰。",tone:"守一",guide:"我为女遂于大明之上矣，至彼至阳之原也；为女入于窈冥之门矣，至彼至阴之原也——天地有官，阴阳有藏（天地各有其职守，阴阳各有其藏纳之处——这些，不需要你去「官阴阳」）——慎守女身，物将自壮（谨慎守护你自身——万物，将自然壮大——不是你去养育万物，而是你守护自身，万物自然壮大——这是「无为而无不为」在养生层面的体现）——我守其一以处其和（我守住那个「一」，处于阴阳的和谐之中）——故我修身千二百岁矣，吾形未常衰。黄帝再拜稽首曰：「广成子之谓天矣！」广成子最后的话：吾与日月参光，吾与天地为常——人其尽死，而我独存乎！这是广成子的宣言——也是《在宥》对「守其一以处其和」境界的最终描绘：不治天下，不撄人心，不多知——守其一，处其和，慎守其身——与日月参光，与天地为常。"}]}),i[19]||(i[19]=n("h2",{id:"五、云将东游·两遇鸿蒙·心养无为",tabindex:"-1"},[e("五、云将东游·两遇鸿蒙·心养无为 "),n("a",{class:"header-anchor",href:"#五、云将东游·两遇鸿蒙·心养无为","aria-label":'Permalink to "五、云将东游·两遇鸿蒙·心养无为"'},"​")],-1)),i[20]||(i[20]=n("h3",{id:"原文-4",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-4","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:u,glossary:x,"default-mode":"classic","aria-label":"在宥·云将问鸿蒙 原文"}),i[21]||(i[21]=n("h3",{id:"生僻字词-4",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-4","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"云将",pinyin:["yún","jiāng"],meaning:"庄子虚构的人物，名字象征「云之将领」，代表有志于治理的人。"},{term:"扶摇之枝",pinyin:["fú","yáo"],meaning:"扶摇：旋风（《逍遥游》中大鹏所乘之风）。扶摇之枝：旋风的旁枝。"},{term:"鸿蒙",pinyin:["hóng","méng"],meaning:"庄子虚构的人物，名字象征混沌初开前的元气状态，代表自然本然之道。"},{term:"拊脾雀跃",pinyin:["fǔ","pí","què","yuè"],meaning:"拊：拍打；脾：大腿。拍打大腿、像雀一样跳跃（无拘无束地嬉游）。"},{term:"倘然止",pinyin:["tǎng","rán"],meaning:"倘然：惊讶、怔住的样子。惊讶地停下来。"},{term:"贽然立",pinyin:["zhì","rán"],meaning:"贽然：恭敬肃立的样子。恭敬地站立。"},{term:"吾弗知",pinyin:["wú","fú","zhī"],meaning:"弗：不。我不知道。"},{term:"游者鞅掌",pinyin:["yāng","zhǎng"],meaning:"鞅掌：繁忙、充实的样子。游者充实自在（游本身就是目的）。"},{term:"以观无妄",pinyin:["yǐ","guān","wú","wàng"],meaning:"以此观照无妄（真实本然）之境。"},{term:"治人之过也",pinyin:["zhì","rén","zhī","guò","yě"],meaning:"这是治理人（干涉人）的过失。"},{term:"毒哉",pinyin:["dú","zāi"],meaning:"毒：危险、有害。太危险了！"},{term:"僊僊乎归矣",pinyin:["xiān","xiān"],meaning:"僊僊：轻盈的样子。轻盈地回去吧！"},{term:"心养",pinyin:["xīn","yǎng"],meaning:"养心！（涵养内心）鸿蒙给云将的全部答案。"},{term:"堕尔形体",pinyin:["duò"],meaning:"堕：放下、忘却。放下你的形体（不执着于形体）。"},{term:"吐尔聪明",pinyin:["tǔ"],meaning:"吐：吐出、放弃。放弃你的聪明（不依赖聪明）。"},{term:"伦与物忘",pinyin:["lún"],meaning:"伦：类别、关系。与万物的关系也一并忘却。"},{term:"大同乎涬溟",pinyin:["xìng","míng"],meaning:"涬溟：混沌无形的元气状态。与混沌无形的元气大同。"}]}),i[22]||(i[22]=n("h3",{id:"核心句引读-4",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-4","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(s,{title:"意！心养！汝徒处无为，而物自化",subtitle:"在宥天下，不是一种政策——而是一种内在状态：养心，无为，不知，不问——万物，自然生长。",lines:[{text:"鸿蒙拊脾雀跃不辍，对云将曰：游！",tone:"本然",guide:"云将东游，过扶摇之枝而适遭鸿蒙。鸿蒙方将拊脾雀跃而游——鸿蒙正在拍着大腿、像雀一样跳跃着嬉游。云将见之，倘然止，贽然立（被震撼，恭敬地站立），问：叟何人邪？叟何为此？鸿蒙的回答只有一个字：「游！」——我在此，只是游。这是鸿蒙第一次亮相——本然状态，就是「游」——无目的、无追求、自在嬉游。"},{text:"云将曰：天气不和，地气郁结，六气不调，四时不节。今我愿合六气之精以育群生，为之奈何？鸿蒙拊脾雀跃掉头曰：吾弗知！吾弗知！",tone:"弗知",guide:"云将的问，是一个治者之问：天气不和、地气郁结、六气不调、四时不节——我愿合六气之精以育群生，为之奈何？鸿蒙拊脾雀跃掉头曰：吾弗知！吾弗知！——我不知道！我不知道！这与第4段广成子拒绝黄帝第一次问完全呼应：治者之问，无答案——因为「治」这个方向本身就错了。鸿蒙的「吾弗知」，不是谦虚，不是逃避——而是：这个问题，不值得回答——因为它预设了一个错误的方向。"},{text:"鸿蒙曰：意！心养！汝徒处无为，而物自化。堕尔形体，吐尔聪明，伦与物忘，大同乎涬溟。解心释神，莫然无魂。",tone:"心养",guide:"云将不得问。又三年，东游，再遇鸿蒙。云将曰：天忘朕邪？——您忘记我了吗？鸿蒙说：浮游不知所求，猖狂不知所往，游者鞅掌，以观无妄——朕又何知！云将说：朕也自以为猖狂，而民随予所往；朕也不得已于民，今则民之放也！愿闻一言——这是云将的转变：从「合六气之精以育群生」的治者之问，到「民之放也」的困惑——他意识到了自己的问题。鸿蒙说：乱天之经，逆物之情——治人之过也。云将再问，鸿蒙终于给出答案：意！心养！——养心！汝徒处无为，而物自化（你只管处于无为的状态，万物自然化育）——堕尔形体（放下对身体的执着），吐尔聪明（放弃对聪明的依赖），伦与物忘（放下与万物的关系），大同乎涬溟（与混沌元气大同）——解心释神，莫然无魂。「心养」——全篇最核心的实践命题——不是积累，不是修炼，不是变得更好——而是：减少，放下，忘却，回归。"},{text:"万物云云，各复其根，各复其根而不知。浑浑沌沌，终身不离。若彼知之，乃是离之。无问其名，无窥其情，物固自生。",tone:"若知即离",guide:"万物云云，各复其根，各复其根而不知——万物各自回归自己的本根，却不知道自己在回归。浑浑沌沌，终身不离——浑浑沌沌，终身不离开（本然）。若彼知之，乃是离之——如果他知道（意识到）这个状态，就已经离开这个状态了——这是《在宥》最深的认识论命题：道，不可以被「知道」。你一旦「知道」了自己是什么人——你就开始按照那个标签行动——你就离开了本然的自己。无问其名，无窥其情，物固自生——不要问它的名字，不要窥探它的实情——万物，本来就自然生长。你，本来就是你——不需要知道自己的名字，不需要窥探自己的实情——你，本来就自然生长。云将曰：天降朕以德，示朕以默。躬身求之，乃今得也。"}]}),i[23]||(i[23]=n("h2",{id:"六、有土者大物·大人之教·天道人道",tabindex:"-1"},[e("六、有土者大物·大人之教·天道人道 "),n("a",{class:"header-anchor",href:"#六、有土者大物·大人之教·天道人道","aria-label":'Permalink to "六、有土者大物·大人之教·天道人道"'},"​")],-1)),i[24]||(i[24]=n("h3",{id:"原文-5",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-5","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:b,glossary:c,"default-mode":"classic","aria-label":"在宥·有土者大物 原文"}),i[25]||(i[25]=n("h3",{id:"生僻字词-5",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-5","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"有大物也",pinyin:["yǒu","dà","wù","yě"],meaning:"拥有大物（国家·天下这样的大东西）。"},{term:"不可以物",pinyin:["bù","kě","yǐ","wù"],meaning:"不可以用对待普通事物的方式来对待（不可以被物所役使）。"},{term:"出入六合",pinyin:["liù","hé"],meaning:"六合：上下四方，即整个宇宙空间。出入于宇宙之间。"},{term:"有问而应之",pinyin:["yǒu","wèn","ér","yìng","zhī"],meaning:"有问才回应（不主动教化）。"},{term:"处乎无响",pinyin:["chǔ","hū","wú","xiǎng"],meaning:"处于无声无响的状态。"},{term:"行乎无方",pinyin:["xíng","hū","wú","fāng"],meaning:"行于无固定方向的状态。"},{term:"大同而无己",pinyin:["dà","tóng","ér","wú","jǐ"],meaning:"大同之中，没有自我（小我消融）。"}]}),i[26]||(i[26]=n("h3",{id:"核心句引读-5",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-5","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(s,{title:"物而不物，故能物物",subtitle:"接触事物，但不被事物所役使——保持内在的自由，才能真正地主宰事物。",lines:[{text:"世俗之人，皆喜人之同乎己而恶人之异于己也。同于己而欲之，异于己而不欲者，以出乎众为心也。夫以出乎众为心者，曷常出乎众哉？",tone:"出众",guide:"第六段，从寓言回到议论——但这一次，议论的对象，从「治天下」转向了「有土者」——拥有土地、统治国家的人。开篇，庄子先描绘世俗之人的心理——皆喜人之同乎己而恶人之异于己（都喜欢别人与自己相同，厌恶别人与自己不同）——以出乎众为心（以超出众人为内心的目标）——夫以出乎众为心者，曷常出乎众哉？（但以超出众人为目标的人，哪里真正超出过众人呢？）。这三句，是对「以出乎众为心」这种心态的精准批判：想要超出众人的人——反而最依赖众人的认可——因为他的「超出」，是以众人为参照的——没有众人，他的「超出」就失去了意义——所以他永远无法真正超出众人。这与第5段鸿蒙「浮游不知所求，猖狂不知所往」完全对照：真正的「超出」，是不知所求、不知所往——不以众人为参照，不以「出众」为目标——这，才是真正的独有。"},{text:"而欲为人之国者，此揽乎三王之利而不见其患者也。此以人之国侥幸也。几何侥幸而不丧人之国乎？其存人之国也，无万分之一；而丧人之国也，一不成而万有余丧矣！悲夫，有土者之不知也！",tone:"侥幸",guide:"从世俗之人，庄子转向「欲为人之国者」——想要治理别人国家的人——此揽乎三王之利而不见其患者也（这是贪取三王的利益，却看不见其中祸患的人）——此以人之国侥幸也（这是用别人的国家来侥幸冒险）——几何侥幸而不丧人之国乎（能有几次侥幸而不丧失别人的国家呢）——其存人之国也，无万分之一（能保存别人国家的可能，连万分之一都没有）——而丧人之国也，一不成而万有余丧矣（而使别人国家灭亡的，一次不成功就有万余次的丧失）——悲夫，有土者之不知也！这一段，是庄子对「治国者」最冷静的概率分析：治国，不是一件成功率高的事——存国的概率：万分之一；丧国的概率：万余倍——但治国者，都以为自己是那个万分之一——这，是「以人之国侥幸」——用别人的国家来赌自己的运气。"},{text:"夫有土者，有大物也。有大物者，不可以物。物而不物，故能物物。明乎物物者之非物也，岂独治天下百姓而已哉！出入六合，游乎九州，独往独来，是谓独有。独有之人，是之谓至贵。",tone:"物而不物",guide:"从批判，庄子转入正面的建构——夫有土者，有大物也（拥有土地的人，拥有的是「大物」——国家·天下，是最大的「物」）——有大物者，不可以物（拥有大物的人，不可以用对待普通事物的方式来对待它——不可以被大物所役使）——物而不物，故能物物（对待事物，但不被事物所役使——所以才能主宰万物，使万物各得其所）。这三句，是《在宥》对「有土者」最深的建议：「物而不物」——不是不接触事物，不是不管事物——而是：接触事物，但不被事物所定义、所役使——保持内在的自由，才能真正地主宰事物。「物物」——使万物各得其所——不是强制管理，而是让万物自然各归其位。明乎物物者之非物也——明白「使万物各得其所的人」本身不是物——出入六合，游乎九州，独往独来，是谓独有——独有之人，是之谓至贵——「独有」——不是独占财富，不是独揽权力——而是：独自拥有道，独自保有本性——不依赖他人，不被外物役使——这，才是真正的「至贵」。"},{text:"大人之教，若形之于影，声之于响，有问而应之，尽其所怀，为天下配。",tone:"大人之教",guide:"大人之教——得道之人的教化——若形之于影，声之于响（像形体与影子的关系，像声音与回响的关系）——这两个比喻，极为精准：形与影——形动，影自然随——形，不需要主动去「教」影如何动；声与响——声发，响自然应。大人之教，就是这样——不主动教化，不强制传授——有问而应之——有人问，才回应——不问，就沉默——尽其所怀，为天下配——充分回应问者所怀抱的，与天下相配合。这与第4段广成子「善哉问乎」完全呼应：广成子拒绝了黄帝第一次的问题——因为那个问题，不是真正的问——第二次，黄帝真正问了，广成子才回应——这，就是「有问而应之」。"},{text:"睹有者，昔之君子；睹无者，天地之友。",tone:"有与无",guide:"颂论形躯，合乎大同（与万物一体相合）——大同而无己（大同之中，没有自我——小我消融）——无己，恶乎得有有（没有自我，哪里还有「有」——执着于有）——睹有者，昔之君子（看到「有」——执着于有形有名——的人，是过去的君子——儒家的君子，执着于有：有仁义，有礼法，有名分——君子，停留在「有」的层面）；睹无者，天地之友（看到「无」——通达于无形无名——的人，是天地的朋友——通达于无：无己，无执，无名——与天地同游，与道同在——这，才是《在宥》真正肯定的境界）。「无己」——这是《逍遥游》「至人无己」的回响——无己，不是消灭自我——而是：小我消融于大同之中——不再执着于「我」与「非我」的分别。"},{text:"何谓道？有天道，有人道。无为而尊者，天道也；有为而累者，人道也。主者，天道也；臣者，人道也。天道之与人道也，相去远矣，不可不察也。",tone:"天道人道",guide:"《在宥》全篇，以这五句作结——何谓道？有天道，有人道——无为而尊者，天道也（无为而自然尊贵的，是天道——日月运行，四时更替，万物生长——没有一件是「有为」的，但没有一件不尊贵）；有为而累者，人道也（有为而带来拖累的，是人道——尧股无胈，胫无毛——这，就是「有为而累」的具体体现）；主者，天道也；臣者，人道也（天道是主，人道是臣——人道，应当服从天道——有为，应当服从无为——治天下，应当服从在宥天下）。天道之与人道也，相去远矣，不可不察也——「不可不察」——这四个字，是《在宥》送给每一个「有土者」的最后警示：你，分清楚了吗？你现在做的，是天道，还是人道？是无为而尊，还是有为而累？是主，还是臣？"}]}),i[27]||(i[27]=w(`<h2 id="脉络逻辑链" tabindex="-1">脉络逻辑链 <a class="header-anchor" href="#脉络逻辑链" aria-label="Permalink to &quot;脉络逻辑链&quot;">​</a></h2><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第1段·立（在宥天下·不闻治天下）</span></span>
<span class="line"><span>    在之也者恐天下淫其性·宥之也者恐天下迁其德</span></span>
<span class="line"><span>    → 全篇命题：在宥天下，不闻治天下</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第2段·析（撄人心之害·喜怒失位·赏罚不给）</span></span>
<span class="line"><span>    大喜毗阳大怒毗阴·喜怒失位·天下之大不足以赏罚</span></span>
<span class="line"><span>    → 治天下的行为，伤害人心与本性</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第3段·论（八者存亡·无为临天下）</span></span>
<span class="line"><span>    八者存可也亡可也·君子不得已莫若无为·尸居龙见</span></span>
<span class="line"><span>    → 无为，然后安其性命之情</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第4段·证（老聃论撄人心·黄帝问广成子）</span></span>
<span class="line"><span>    女慎无撄人心·罪在撄人心·守其一以处其和</span></span>
<span class="line"><span>    → 从历史证明：撄人心是罪，守一是道</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第5段·证（云将东游·两遇鸿蒙·心养无为）</span></span>
<span class="line"><span>    心养·汝徒处无为而物自化·若彼知之乃是离之·物固自生</span></span>
<span class="line"><span>    → 心养无为的实践：万物自然生长</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第6段·合（有土者大物·大人之教·天道人道）</span></span>
<span class="line"><span>    物而不物故能物物·有问而应之·无为而尊者天道也</span></span>
<span class="line"><span>    → 全篇收束：天道为主，人道为臣，不可不察</span></span></code></pre></div><p><strong>全篇主线</strong>：从「在宥天下」的命题立起，析撄人心之害，论八者存亡与无为临天下，经老聃论撄心、广成子守一、鸿蒙心养的双重印证，最终收于「天道人道相去远矣」——治天下，先养心。</p><h2 id="三问解读" tabindex="-1">三问解读 <a class="header-anchor" href="#三问解读" aria-label="Permalink to &quot;三问解读&quot;">​</a></h2><h3 id="第一问-「在宥天下」究竟是什么意思" tabindex="-1">第一问：「在宥天下」究竟是什么意思？ <a class="header-anchor" href="#第一问-「在宥天下」究竟是什么意思" aria-label="Permalink to &quot;第一问：「在宥天下」究竟是什么意思？&quot;">​</a></h3><p>「在宥」二字，是全篇的核心，也是最容易被误解的地方。</p><p>常见的误解有两种：误解一——在宥 = 放任不管（认为庄子主张什么都不做，任由天下自生自灭——这是把「在宥」等同于「消极无为」）；误解二——在宥 = 宽松管理（认为庄子只是主张少管一点，用更温和的方式治理——这是把「在宥」等同于「软性治理」）。</p><p>庄子的本意，两者都不是。回到原文：「在之也者，恐天下之淫其性也；宥之也者，恐天下之迁其德也。」「在宥」的动机，是「恐」——是担心，是保护——在：担心天下的本性被扰乱，所以让其自在；宥：担心天下的本德被改变，所以宽容不干涉。</p><p>「在宥」，是一种积极的保护——不是消极地不管，而是：主动地保护本性不被干涉——这种保护，以「不干涉」的方式实现。</p><p>一个比喻：一棵树，在土地里自然生长——「在宥」，是保护这棵树不被人随意修剪、移植、嫁接——不是不给它浇水，不是不给它阳光——而是：不去改变它本来的生长方向。「治天下」，是修剪——按照人的想法，把树修成某种形状——看起来更整齐，更有秩序——但树，失去了本来的形状。「在宥天下」，是不修剪——让树按照自己的方式生长——可能不整齐，可能不符合人的审美——但树，是本然的。</p><h3 id="第二问-「撄人心」为什么是罪" tabindex="-1">第二问：「撄人心」为什么是罪？ <a class="header-anchor" href="#第二问-「撄人心」为什么是罪" aria-label="Permalink to &quot;第二问：「撄人心」为什么是罪？&quot;">​</a></h3><p>老聃说：「罪在撄人心。」这是《在宥》最具争议的命题——因为它把一切「治理」都定性为「撄人心」，把一切「撄人心」都定性为「罪」。</p><p>理解这个命题，需要先理解老聃对「人心」的描述：「偾骄而不可系者，其唯人心乎！」人心，是天地间最不可控的存在——柔软时无坚不摧，锋利时无物不伤，热时焦火，冷时凝冰，快时瞬息万里。</p><p>「撄人心」的问题，不在于动机——黄帝以仁义撄人心，动机是好的；尧舜股无胈、胫无毛，牺牲是真实的——但结果，是天下大乱。为什么好的动机，带来坏的结果？庄子的逻辑是：撄人心（无论动机好坏）→ 人心被激发（超出本然节度）→ 喜怒失位·居处无常·思虑不自得 → 本性失衡·向两个极端分化 → 一端：盗跖（极恶），一端：曾史（极善）→ 极善激发极恶（曾史是桀跖嚆矢）→ 儒墨毕起·斤锯绳墨椎凿 → 天下脊脊大乱。</p><p>「撄人心」是罪，不是因为动机坏——而是因为：任何对人心的激发，都会打破人心本然的平衡——而打破平衡之后，没有任何力量能够重新控制它——因为人心，偾骄而不可系。这是一个系统性的命题：你激发了人心的善——人心的恶，也同时被激发——因为善与恶，是同一个失衡的两面——你无法只激发善，不激发恶——这，是「撄人心」最深的危险。所以老聃说：「女慎，无撄人心。」不是「你要激发善的一面」——而是：根本不要去撄它。</p><h3 id="第三问-「心养」在今天意味着什么" tabindex="-1">第三问：「心养」在今天意味着什么？ <a class="header-anchor" href="#第三问-「心养」在今天意味着什么" aria-label="Permalink to &quot;第三问：「心养」在今天意味着什么？&quot;">​</a></h3><p>鸿蒙给云将的答案，只有两个字：「心养。」然后展开：「汝徒处无为，而物自化。堕尔形体，吐尔聪明，伦与物忘，大同乎涬溟。解心释神，莫然无魂。」</p><p>「心养」，不是心理治疗，不是冥想课程——它是一种根本性的生命态度：堕尔形体（放下对身体的执着——不以形体为自我）；吐尔聪明（放弃对聪明的依赖——不以智识为资本）；伦与物忘（放下与万物的关系——不以关系定义自我）；大同乎涬溟（与混沌元气大同——回到本然）。四个「放下」，是「心养」的具体内容——不是积累，不是修炼，不是变得更好——而是：减少，放下，忘却，回归。</p><p>在今天，「心养」面对的是什么？今天的「撄人心」，比庄子时代更密集、更精准：信息流——每一条推送，都在撄你的心——激发你的喜怒，激发你的欲望，激发你的恐惧；绩效评估——每一个KPI，都在撄你的心——让你的喜怒，与数字挂钩；社交比较——每一次点赞，都在撄你的心——「以出乎众为心」。</p><p>「心养」，在今天意味着：信息流不断激发喜怒→堕尔形体——不以情绪反应为自我；绩效指标定义价值→吐尔聪明——不以外部评价为依据；社交比较制造焦虑→伦与物忘——不以关系和比较定义自我；永远在线·永远响应→处乎无响·行乎无方——不必永远在线；追求更多·更快·更好→物固自生——万物本来就自然生长。</p><p>「心养」，不是逃避——不是关掉手机，不是辞职隐居——而是：在参与一切的同时，不被一切所役使——「物而不物，故能物物」——接触事物，但不被事物定义——这，才是今天「心养」的真实意涵。</p><h2 id="现代思考与启发" tabindex="-1">现代思考与启发 <a class="header-anchor" href="#现代思考与启发" aria-label="Permalink to &quot;现代思考与启发&quot;">​</a></h2><p><strong>领导力：从「治」到「在宥」</strong></p><blockquote><p>《在宥》对「治天下」的批判，在今天的管理与领导力语境中，极具启发。庄子的命题：「有大物者，不可以物。物而不物，故能物物。」翻译成今天的语言：管理大组织的人，不能被组织所役使；接触事务但不被事务定义，才能真正主导事务。「在宥」式的领导力，有三个特征：第一·有问而应，不主动干涉——「大人之教，若形之于影，声之于响，有问而应之」——不主动推行自己的想法，等待真正的问题出现，再充分回应——这不是懒惰，而是尊重——尊重每个人找到自己答案的过程。第二·贵以身，爱以身——「贵以身于为天下，则可以托天下」——真正可以被托付的领导者，不是那种「以天下为己任」、舍身忘我的人——而是那种珍视自身本性的人——因为珍视自身本性的人，才懂得珍视他人的本性。第三·不得已而临莅，莫若无为——「故君子不得已而临莅天下，莫若无为」——真正的领导者，是「不得已」才去领导的——不是主动争取权力，而是在不得已的情况下承担责任——这种「不得已」，保证了领导者不会把权力当成目的。</p></blockquote><p><strong>教育：从「撄心」到「心养」</strong></p><blockquote><p>《在宥》对「撄人心」的批判，对今天的教育有深刻的启示。今天的教育，大量是「撄心」的：排名与竞争——激发孩子的喜怒，让他们的自我价值与成绩挂钩——这是「撄人心」最典型的形式；标准答案——告诉孩子什么是对的，什么是错的——这是「迁其德」——改变本真之德。「说仁邪，是乱于德也；说义邪，是悖于理也」——当我们不断告诉孩子「你要善良·你要勤奋·你要有责任感」——我们以为在培养德性——实则，是在「乱于德」——因为真正的德，不是被告知的，而是本然流出的。「心养」式的教育，意味着：不激发，而保护——不灌输，而等待——不比较，而允许——让本性，自然流淌。这不是放任，而是：相信每个孩子，都有「物固自生」的力量——你只需要，不去阻碍它。</p></blockquote><p><strong>自我：从「多知为败」到「若彼知之乃是离之」</strong></p><blockquote><p>《在宥》对「知」的批判，在今天的信息时代，有特别的意义。广成子说「多知为败」——今天，我们每天接收的信息量，是庄子时代的人一生都无法想象的——我们，活在「多知」的极端状态里。但更深的问题，是鸿蒙说的：「若彼知之，乃是离之。」我们不只是知得太多——我们还在不断地「知道自己」——MBTI测试、心理咨询、自我分析——我们用各种工具，去「知道」自己是什么人——但鸿蒙说：你一旦「知道」了——你就离开了。你「知道」自己是INTJ——你就开始按照INTJ的方式行动——你就离开了本然的自己。「浑浑沌沌，终身不离」——不是说不要了解自己——而是说：不要把「了解自己」变成一个固定的标签——因为本然的自己，是浑浑沌沌的，是流动的，是不可固定的——任何固定，都是离开。「无问其名，无窥其情，物固自生」——你，本来就是你——不需要知道自己的名字，不需要窥探自己的实情——你，本来就自然生长。</p></blockquote><p><strong>政治哲学：天道与人道的现代意义</strong></p><blockquote><p>《在宥》最后的命题：「无为而尊者，天道也；有为而累者，人道也。主者，天道也；臣者，人道也。」这个命题，在今天的政治哲学语境中，可以这样理解：天道——系统的自组织能力——任何复杂系统（生态·市场·社会），都有自组织的能力——不需要外力强制，系统会自然找到平衡——这，是「无为而尊」的天道。人道——外力的干预——当人用外力干预系统——无论动机多好，都会带来「累」——因为系统的复杂性，远超人的认知能力——这，是「有为而累」的人道。庄子不是说「永远不干预」——他说的是：「主者，天道也；臣者，人道也」——干预，应当服从系统的自组织逻辑——人道，应当是天道的臣，而不是天道的主。今天，这个命题的意义在于：在任何管理与治理中——先问：这个系统的「天道」是什么？它的自组织逻辑是什么？我的干预，是在顺应这个逻辑，还是在违背它？「不可不察也。」</p></blockquote><h2 id="关键词索引" tabindex="-1">关键词索引 <a class="header-anchor" href="#关键词索引" aria-label="Permalink to &quot;关键词索引&quot;">​</a></h2><h3 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h3><table tabindex="0"><thead><tr><th>概念</th><th>出处</th><th>核心含义</th></tr></thead><tbody><tr><td>在宥</td><td>第1段</td><td>全篇核心词。在：自在，让其自在；宥：宽容，不加干涉。「在宥天下」：以不干涉的方式，保护天下的本性不被扰乱、不被改变</td></tr><tr><td>淫其性</td><td>第1段</td><td>扰乱、过度刺激本性，使本性失去自然节度。非「放纵本性」，而是「本性被外力过度激发」</td></tr><tr><td>迁其德</td><td>第1段</td><td>改变、迁移本真之德，使德不再是自己的德</td></tr><tr><td>性命之情</td><td>第2·3段</td><td>本性与生命的真实情感，本然的生命状态。非被激发的喜怒，非被规范的善恶</td></tr><tr><td>撄人心</td><td>第2·4段</td><td>扰乱、触动人心，使人心超出本然节度。老聃的核心警告：「女慎，无撄人心。」无论动机好坏，撄人心都会导致人心失衡，天下大乱</td></tr><tr><td>偾骄而不可系</td><td>第4段</td><td>奔腾不驯而无法束缚。描述人心的本质——最强大、最不可控</td></tr><tr><td>嚆矢</td><td>第4段</td><td>响箭，比喻先导、开端。「曾史是桀跖嚆矢」——极善，是极恶的先导</td></tr><tr><td>绝圣弃知</td><td>第4段</td><td>断绝圣人之道，抛弃机巧之知。《胠箧》与《在宥》共同的核心命题</td></tr><tr><td>窈窈冥冥·昏昏默默</td><td>第4段</td><td>描述至道的性质：深远幽暗、混沌沉默、不可言说、不可测度。至道，只能处于其中，不能被「知道」</td></tr><tr><td>多知为败</td><td>第4段</td><td>过多的知识是失败的根源。广成子对黄帝的核心教导</td></tr><tr><td>守其一以处其和</td><td>第4段</td><td>守住那个「一」（道的本体），处于阴阳的和谐之中。广成子修身千二百岁的根本方法</td></tr><tr><td>心养</td><td>第5段</td><td>全篇最核心的实践命题。养心，涵养内心。鸿蒙给云将的全部答案。具体内容：堕形体·吐聪明·伦与物忘·大同乎涬溟·解心释神·莫然无魂</td></tr><tr><td>若彼知之，乃是离之</td><td>第5段</td><td>如果他知道（意识到）这个状态，就已经离开这个状态了。《在宥》最深的认识论命题：道，不可以被「知道」</td></tr><tr><td>物固自生</td><td>第5段</td><td>万物本来就自然生长。不需要你去养育万物，万物本来就自然生长</td></tr><tr><td>物而不物，故能物物</td><td>第6段</td><td>接触事物但不被事物役使，所以才能主宰万物使其各得其所</td></tr><tr><td>独有</td><td>第6段</td><td>独自拥有道，独自保有本性，不依赖他人，不被外物役使。《在宥》对最高境界的命名</td></tr><tr><td>睹有者·睹无者</td><td>第6段</td><td>睹有者：执着于有形有名，是「昔之君子」（儒家君子）；睹无者：通达于无形无名，是「天地之友」</td></tr><tr><td>天道·人道</td><td>第6段</td><td>天道：无为而尊，是主；人道：有为而累，是臣。全篇收束的核心对立</td></tr></tbody></table><h3 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h3><p>如果《在宥》全篇，只能用一句话来总结——</p><blockquote><p><strong>「意！心养！汝徒处无为，而物自化。」</strong></p></blockquote><p>如果只能用一个问题来收束——</p><blockquote><p><strong>「天道之与人道也，相去远矣——你，分清楚了吗？」</strong></p></blockquote><h2 id="参考来源" tabindex="-1">参考来源 <a class="header-anchor" href="#参考来源" aria-label="Permalink to &quot;参考来源&quot;">​</a></h2><ul><li>《庄子·外篇·在宥》</li></ul>`,40))])}}});export{C as __pageData,v as default};
